13	)
14	
15	// The connectivity form is driven entirely through Update, and the one command
16	// it returns shells out to Docker — so it is asserted on, never executed.
17	
18	func connectivityContainers() []docker.NetworkContainer {
19		return []docker.NetworkContainer{
20			{Name: "api", IPv4: "172.18.0.2"},
21			{Name: "db", IPv4: "172.18.0.3"},
22			{Name: "sidecar-with-no-address"},
23		}
24	}
25	
26	func newConnectivityForm(t *testing.T) *ConnectivityTestForm {
27		t.Helper()
28		return newConnectivityTestForm("web", "net22222", "netshoot", connectivityContainers(), 120, 30)
29	}
30	
31	func key(t *testing.T, f *ConnectivityTestForm, names ...string) (*ConnectivityTestForm, tea.Cmd) {
32		t.Helper()
33		var cmd tea.Cmd
34		for _, name := range names {
35			f, cmd = f.Update(testutil.Key(name))
36		}
37		return f, cmd
38	}
39	
40	// onTypeField moves the focus to the test type. It goes backwards on purpose:
41	// ↓ from the target field walks the container suggestions first, so the number
42	// of presses would depend on how many containers the fixture has.
43	func onTypeField(t *testing.T, f *ConnectivityTestForm) *ConnectivityTestForm {
44		t.Helper()
45		f, _ = key(t, f, "up", "up")
46		if f.focusedField != cFieldType {
47			t.Fatalf("focus = %d, want the type field", f.focusedField)
48		}
49		return f
50	}
51	
52	// ── Field layout ─────────────────────────────────────────────────────────────
53	
54	// The port only means something for curl and netcat, and hiding it moves the
55	// submit button up a slot. Getting that wrong makes Enter do nothing on the
56	// button the user is looking at.
57	func TestThePortFieldAndTheSubmitSlotMoveWithTheTestType(t *testing.T) {
58		f := newConnectivityForm(t)
59	
60		if f.isPortActive() {
61			t.Error("ping was given a port field")
62		}
63		if f.numFields() != 3 || f.submitIdx() != cFieldPort {
64			t.Errorf("ping: %d fields, submit at %d — want 3 and the third slot", f.numFields(), f.submitIdx())
65		}
66	
67		f = onTypeField(t, f)
68		f, _ = key(t, f, "right")
69		if !f.isPortActive() {
70			t.Fatalf("testType = %v, want curl after one step right", f.testType)
71		}
72		if f.numFields() != 4 || f.submitIdx() != cFieldSubmit {
73			t.Errorf("curl: %d fields, submit at %d — want 4 and the fourth slot", f.numFields(), f.submitIdx())
74		}
75	}
76	
77	// Rule 132: a closed set cycles with ← / →, and wraps in both directions.
78	func TestTheTestTypeCyclesInBothDirections(t *testing.T) {
79		f := onTypeField(t, newConnectivityForm(t))
80	
81		f, _ = key(t, f, "right")
82		if f.testType != testHTTP {
83			t.Errorf("testType = %v, want curl", f.testType)
84		}
85		f, _ = key(t, f, "right", "right")
86		if f.testType != testPing {
87			t.Errorf("testType = %v, want it to have wrapped back to ping", f.testType)
88		}
89		f, _ = key(t, f, "left")
90		if f.testType != testNetcat {
91			t.Errorf("testType = %v, want it to wrap backwards to netcat", f.testType)
92		}
93	}
94	
95	// The arrows only cycle the field that owns them; on any other field they are
96	// navigation and must leave the type alone.
97	func TestTheArrowsDoNotCycleTheTypeFromAnotherField(t *testing.T) {
98		f := newConnectivityForm(t)
99	
100		f, _ = key(t, f, "right", "left")
101	
102		if f.testType != testPing {
103			t.Errorf("testType = %v, want it untouched from the target field", f.testType)
104		}
105	}
106	
107	// D21, pinning the invariant rather than the code: cycling the type can shrink
108	// the field count, and the clamp that guarded that in the left/right handlers
109	// could not fire — cycling only happens while cFieldType is focused, and that
110	// index is below numFields() in every mode. Both clamps are gone (the shape D5
111	// records for CreationForm); this test is what keeps the invariant they were
112	// guarding true without them.
113	func TestCyclingTheTypeNeverStrandsTheFocus(t *testing.T) {
114		f := onTypeField(t, newConnectivityForm(t))
115	
116		for i, step := range []string{"right", "right", "right", "left", "left", "left"} {
117			f, _ = key(t, f, step)
118			if f.focusedField >= f.numFields() {
119				t.Fatalf("after %d cycles the focus is on field %d of %d", i+1, f.focusedField, f.numFields())
120			}
121		}
122	}
123	
124	// Rule 135: ↑ / ↓ navigate fields, and they wrap so every control is reachable
125	// in one direction.
126	func TestFieldNavigationWrapsAround(t *testing.T) {
127		f := newConnectivityForm(t)
128	
129		f, _ = key(t, f, "up")
130		if f.focusedField != f.submitIdx() {
131			t.Errorf("focus = %d, want up from the first field to land on submit", f.focusedField)
132		}
133		f, _ = key(t, f, "down")
134		if f.focusedField != cFieldTarget {
135			t.Errorf("focus = %d, want it back on the target", f.focusedField)
136		}
137	}
138	
139	// Only the focused input takes typing — the port field must not swallow
140	// characters meant for the target.
141	func TestTypingReachesTheFocusedInputOnly(t *testing.T) {
142		f := newConnectivityForm(t)
143	
144		for _, msg := range testutil.Type("10.0.0.5") {
145			f, _ = f.Update(msg)
146		}
147		if f.targetInput.Value() != "10.0.0.5" {
148			t.Errorf("target = %q, want what was typed", f.targetInput.Value())
149		}
150	
151		f = onTypeField(t, f)
152		f, _ = key(t, f, "right") // curl, so the port field appears
153		f, _ = key(t, f, "down")  // onto the port
154		for _, msg := range testutil.Type("8443") {
155			f, _ = f.Update(msg)
156		}
157		if f.portInput.Value() != "8443" {
158			t.Errorf("port = %q, want what was typed", f.portInput.Value())
159		}
160		if f.targetInput.Value() != "10.0.0.5" {
161			t.Errorf("target = %q, want it left alone", f.targetInput.Value())
162		}
163	}
164	
165	// ── The container suggestions ────────────────────────────────────────────────
166	
167	// The list exists so the user does not have to read an IP off another screen
168	// and retype it, so browsing it has to fill the field.
169	func TestBrowsingTheSuggestionsFillsTheTarget(t *testing.T) {
170		f := newConnectivityForm(t)
171	
172		f, _ = key(t, f, "down")
173		if f.targetInput.Value() != "172.18.0.2" {
174			t.Fatalf("target = %q, want the first container's address", f.targetInput.Value())
175		}
176		f, _ = key(t, f, "down")
177		if f.targetInput.Value() != "172.18.0.3" {
178			t.Errorf("target = %q, want the second container's address", f.targetInput.Value())
179		}
180	}
181	
182	// Stepping back off the top of the list is how the user leaves it, and the
183	// selection has to be released rather than sticking on the first entry.
184	func TestSteppingBackOffTheSuggestionListReleasesIt(t *testing.T) {
185		f := newConnectivityForm(t)
186		f, _ = key(t, f, "down", "down") // into the list, second entry
187	
188		f, _ = key(t, f, "up", "up")
189	
190		if f.containerListIdx != -1 {
191			t.Errorf("containerListIdx = %d, want nothing selected", f.containerListIdx)
192		}
193		if f.focusedField != cFieldTarget {
194			t.Errorf("focus = %d, want it still on the target field", f.focusedField)
195		}
196	}
