198	// Once the user types, the highlight is stale — it refers to a value they have
199	// just replaced.
200	func TestTypingClearsTheSuggestionHighlight(t *testing.T) {
201		f := newConnectivityForm(t)
202		f, _ = key(t, f, "down")
203	
204		for _, msg := range testutil.Type("9") {
205			f, _ = f.Update(msg)
206		}
207	
208		if f.containerListIdx != -1 {
209			t.Errorf("containerListIdx = %d, want the highlight dropped once typing started", f.containerListIdx)
210		}
211	}
