216		f := newConnectivityForm(t)
217	
218		for range len(connectivityContainers()) {
219			f, _ = key(t, f, "down")
220		}
221		f, _ = key(t, f, "down")
222	
223		if f.focusedField != cFieldType {
224			t.Errorf("focus = %d, want the next field once the list is exhausted", f.focusedField)
225		}
226	}
