228	// A form opened on a network with nothing attached has no list, and ↓ is plain
229	// navigation from the first keystroke.
230	func TestWithNoContainersTheArrowsOnlyNavigate(t *testing.T) {
231		f := newConnectivityTestForm("web", "net22222", "netshoot", nil, 120, 30)
232	
233		f, _ = key(t, f, "down")
234	
235		if f.focusedField != cFieldType {
236			t.Errorf("focus = %d, want the type field", f.focusedField)
