242	func TestTheCommandMatchesTheSelectedTest(t *testing.T) {
243		cases := []struct {
244			name     string
245			testType connectivityTestType
246			port     string
247			want     string
248		}{
249			{"ping ignores the port", testPing, "8080", "ping -c 3 10.0.0.5"},
250			{"the HTTP test builds a URL", testHTTP, "8080", "wget -S -O- -T 5 http://10.0.0.5:8080"},
251			{"netcat probes the port", testNetcat, "5432", "nc -zv -w 5 10.0.0.5 5432"},
