283	// with a running state the user then has to wait out.
284	func TestSubmittingWithNoTargetDoesNothing(t *testing.T) {
285		f := newConnectivityForm(t)
286		f.targetInput.SetValue("   ")
287	
288		f, cmd := key(t, f, "up", "enter")
