326	// ── Results ──────────────────────────────────────────────────────────────────
327	
328	// A non-zero exit with output is not a failed test: curl exiting 52 with a
329	// transcript is the answer. Only an exit with nothing to show is an error.
330	func TestAResultWithOutputAndAnExitCodeIsAWarningNotAFailure(t *testing.T) {
