443	// ── Rendering ────────────────────────────────────────────────────────────────
444	
445	// Rule 134: the shortcuts live in the header, so nothing in the viewport may
446	// spell out a key.
447	func TestTheFormCarriesNoInlineHelp(t *testing.T) {
448		f := newConnectivityForm(t)
449	
450		for _, view := range []string{f.View(), runningView(f), resultsView(f)} {
