472	// and hiding it would suggest otherwise.
473	func TestAContainerWithNoAddressIsStillListed(t *testing.T) {
474		f := newConnectivityForm(t)
475	
476		view := f.View() // the target field is focused, so the list is shown
477		if !strings.Contains(view, "sidecar-with-no-address") {
