486	// to take it off screen or it crowds out the rest of the form.
487	func TestTheSuggestionsAreOnlyShownOnTheTargetField(t *testing.T) {
488		f := newConnectivityForm(t)
489		f, _ = key(t, f, "up") // onto submit
490	
491		if strings.Contains(f.View(), "Containers on this network") {
492			t.Error("the suggestion list is shown while another field is focused")
493		}
494	}
495	
496	func TestTruncateResultLine(t *testing.T) {
497		cases := []struct {
498			in   string
499			max  int
500			want string
501		}{
502			{"short", 10, "short"},
503			{"exactly-10", 10, "exactly-10"},
504			{"much longer than allowed", 10, "much long…"},
505			{"anything", 0, ""},
506			{"anything", -1, ""},
507		}
508		for _, tc := range cases {
