373			entry := m.registryEntryActions()
374			refresh := "Refresh"
375			if m.registryDrillIn().Enabled() {
376				refresh = "Refresh group members"
377			}
378			return append(base,
379				shortcut.Shortcut{Key: keymap.New, Description: "New registry", Disabled: !m.registryCreate().Enabled()},
380				shortcut.Shortcut{Key: keymap.Edit, Description: "Edit registry", Disabled: !entry.Enabled()},
381				shortcut.Shortcut{Key: keymap.Auth, Description: "Log in or out", Disabled: !entry.Enabled()},
382				shortcut.Shortcut{Key: keymap.Delete, Description: "Remove", Disabled: !entry.Enabled()},
383				shortcut.Shortcut{Key: "→", Description: "Show members", Disabled: !m.registryDrillIn().Enabled()},
384				shortcut.Shortcut{Key: "←", Description: "Back to registries", Disabled: !m.registryDrillOut().Enabled()},
385				shortcut.Shortcut{Key: "ctrl+r", Description: refresh},
386				shortcut.Shortcut{Key: "?", Description: "Help"},
387			)
388		}
389	
390		base = append(base,
391			shortcut.Shortcut{Key: "ctrl+r", Description: "Refresh"},
392			shortcut.Shortcut{Key: "?", Description: "Help"},
393		)
394		return base
395	}
396	
397	// View renders the view (Rule 112: forms in viewport, modals centered)
398	func (m Model) View() string {
399		// Priority 0: registry browser (viewport)
400		if m.registryBrowser != nil {
401			return m.registryBrowser.View()
402		}
403		// Priority 1: launch form (viewport)
404		if m.launchForm != nil {
405			return m.launchForm.View()
406		}
407		// Priority 2: resource creation form (viewport)
408		if m.resourceForm != nil {
409			return m.resourceForm.View()
410		}
411		// Priority 3: registry form (viewport)
412		if m.registryForm != nil {
413			return m.registryForm.View()
414		}
415		// Priority 4: connectivity test form (viewport)
416		if m.connectivityForm != nil {
417			return m.connectivityForm.View()
418		}
419		// Priority 5: whichever modal is open (centered)
420		if modal := m.modalView(); modal != "" {
421			return lipgloss.Place(
422				m.width, m.height,
423				lipgloss.Center, lipgloss.Center,
424				modal,
425				lipgloss.WithWhitespaceBackground(theme.ColorBackground),
426			)
427		}
428		// Priority 6: network inspect form (viewport)
429		if m.networkInspectForm != nil {
430			return m.networkInspectForm.View()
431		}
432		// Priority 7: normal view by active tab
433		return m.renderNormalView()
434	}
435	
436	// renderNormalView renders the active tab's content
437	func (m Model) renderNormalView() string {
438		switch m.activeTab {
439		case tabNetworks:
440			return m.renderNetworksView()
441		case tabVolumes:
442			return m.renderVolumesView()
443		case tabRegistries:
444			return m.renderRegistriesView()
445		default:
446			return m.renderImagesView()
447		}
448	}
449	
450	// renderRegistriesView renders the registries table. An empty table stays a
451	// table (Rule 139) — the count lives in GetHeaderInfo's "Registries" field.
452	func (m Model) renderRegistriesView() string {
453		return m.registryTable.View()
454	}
455	
456	// renderImagesView renders the images table.
457	//
458	// The load says so in the footer, with a spinner, and the table stays on
459	// screen: a body that swapped itself for a spinner lost its header and its
460	// columns for the length of every refresh. An empty table — loaded and
461	// genuinely empty, or filtered down to nothing — stays a table too (Rule 139):
462	// its header and no rows, with the count in GetHeaderInfo's "Images" field.
463	func (m Model) renderImagesView() string {
464		return m.imageTable.View()
465	}
466	
467	// renderNetworksView renders the networks table (Rule 139: no body message).
468	func (m Model) renderNetworksView() string {
469		return m.networkTable.View()
470	}
471	
472	// renderVolumesView renders the volumes table (Rule 139: no body message).
473	func (m Model) renderVolumesView() string {
474		return m.volumeTable.View()
475	}
476	
477	// GetHelpContent returns help content for the OCI resources view (Rule 114)
478	func (m Model) GetHelpContent() help.Content {
479		return help.Content{
480			Title:       "OCI Resources",
481			Description: "This view manages local Docker/OCI resources: Images (with CVE scanning), Networks, Volumes, and Registries. Use Tab/Shift+Tab to switch between tabs.",
482			KeyBindings: []help.KeyBinding{
483				{Key: "tab / shift+tab", Description: "Switch between Images, Networks, Volumes, and Registries tabs"},
484				{Key: "enter (Images)", Description: "View scan details for the selected image (loads from cache; falls back to scan if not yet scanned)"},
485				{Key: "N (Images)", Description: "Launch a container from the selected image"},
486				{Key: "S (Images)", Description: "Launch a scan for the selected image"},
487				{Key: "A (Images)", Description: "Scan every image. The confirmation carries a checkbox to purge the cached results first — unchecked, only what has never been scanned is scanned"},
488				{Key: "A (Images)", Description: "Scan all unscanned images using config defaults"},
