func isModalSwitch(clauses []caseClause) bool {
	var yes, no bool
	for _, clause := range clauses {
		for _, key := range clause.keys {
			switch key {
			case "y":
				yes = true
			case "n":
				no = true
			}
		}
	}
	return yes && no
